//! IxVM model advice: the prover-side witness for mutual and nested
//! inductive blocks (`IxVM.Model`).
//!
//! IxVM checks such a block against a *model* made of ordinary
//! declarations it type-checks (`KernelModeled::check_family`). The model is
//! generated by the certified kernel's modeller on the Lean side and is
//! untrusted advice: nothing binds it to the block by hashing, and neither
//! the claim nor the claimed environment changes with it. It reaches the
//! kernel as extra records, hints and blobs on channels 2, 3 and 4, and as
//! one payload per block on channel 7.
//!
//! # Encoding
//!
//! Lean hands the advice over with the environment
//! (`IxVM.ClaimHarness.modelAdviceBytes`, `Aiur.EnvHandle`). All integers are
//! little-endian `u64`; every section ascends by address bytes:
//!
//! ```text
//! advice   = "IXVMMDL\0" u64(version = 1)
//!            section(records) section(hints) section(blobs)
//!            section(payloads) section(deps)
//! records  = u64(n) (address u64(len) bytes)*n     -- serialized constants
//! hints    = u64(n) (address u64(tag))*n           -- `hint_tag` encoding
//! blobs    = u64(n) (address u64(len) bytes)*n
//! payloads = u64(n) (address u64(len) bytes)*n     -- keyed by muts block
//! deps     = u64(n) (address u64(k) address*k)*n   -- keyed by muts block
//! ```

use std::sync::Arc;

use ix_common::address::Address;
use rustc_hash::FxHashMap;

use crate::lazy::LazyConstant;

const MAGIC: &[u8; 8] = b"IXVMMDL\0";
const VERSION: u64 = 1;

/// The model advice of one environment.
#[derive(Clone, Debug, Default)]
pub struct ModelAdvice {
  /// Generated model records, by address.
  pub records: FxHashMap<Address, LazyConstant>,
  /// Reducibility hints of the generated definitions, as `hint_tag`s.
  pub hints: FxHashMap<Address, u64>,
  /// Literal blobs of the generated records.
  pub blobs: FxHashMap<Address, Vec<u8>>,
  /// Per inductive block, the payload `KernelModeled::read_payload` reads
  /// on channel 7. Empty for a block the modeller did not model.
  pub payloads: FxHashMap<Address, Vec<u8>>,
  /// Per modeled block, the records and recursors its payload names: the
  /// extra byte scope of a run that checks the block.
  pub deps: FxHashMap<Address, Vec<Address>>,
}

impl ModelAdvice {
  pub fn is_empty(&self) -> bool {
    self.records.is_empty()
      && self.hints.is_empty()
      && self.blobs.is_empty()
      && self.payloads.is_empty()
      && self.deps.is_empty()
  }

  /// Decode the advice encoding.
  pub fn decode(bytes: &[u8]) -> Result<Self, String> {
    let mut r = Reader { bytes, pos: 0 };
    if r.take(8)? != MAGIC {
      return Err("model advice: bad magic".into());
    }
    let version = r.u64()?;
    if version != VERSION {
      return Err(format!("model advice: unsupported version {version}"));
    }
    let mut advice = Self::default();
    for _ in 0..r.count()? {
      let addr = r.address()?;
      let bytes: Arc<[u8]> = r.bytes()?.into();
      advice.records.insert(addr, LazyConstant::from_bytes(bytes));
    }
    for _ in 0..r.count()? {
      let addr = r.address()?;
      advice.hints.insert(addr, r.u64()?);
    }
    for _ in 0..r.count()? {
      let addr = r.address()?;
      advice.blobs.insert(addr, r.bytes()?.to_vec());
    }
    for _ in 0..r.count()? {
      let addr = r.address()?;
      advice.payloads.insert(addr, r.bytes()?.to_vec());
    }
    for _ in 0..r.count()? {
      let addr = r.address()?;
      let n = r.count()?;
      let deps = (0..n).map(|_| r.address()).collect::<Result<_, _>>()?;
      advice.deps.insert(addr, deps);
    }
    if r.pos != bytes.len() {
      return Err("model advice: trailing bytes".into());
    }
    Ok(advice)
  }
}

struct Reader<'a> {
  bytes: &'a [u8],
  pos: usize,
}

impl<'a> Reader<'a> {
  fn take(&mut self, n: usize) -> Result<&'a [u8], String> {
    let end = self
      .pos
      .checked_add(n)
      .filter(|&end| end <= self.bytes.len())
      .ok_or("model advice: truncated")?;
    let out = &self.bytes[self.pos..end];
    self.pos = end;
    Ok(out)
  }

  fn u64(&mut self) -> Result<u64, String> {
    let bytes = self.take(8)?;
    Ok(u64::from_le_bytes(bytes.try_into().expect("eight bytes")))
  }

  /// A length or count, bounded by the bytes left so a corrupt encoding
  /// cannot request an allocation larger than itself.
  fn count(&mut self) -> Result<usize, String> {
    let n = usize::try_from(self.u64()?)
      .map_err(|e| format!("model advice: count overflows: {e}"))?;
    if n > self.bytes.len() - self.pos {
      return Err("model advice: count exceeds the encoding".into());
    }
    Ok(n)
  }

  fn address(&mut self) -> Result<Address, String> {
    Address::from_slice(self.take(32)?)
      .map_err(|e| format!("model advice: bad address: {e}"))
  }

  fn bytes(&mut self) -> Result<&'a [u8], String> {
    let n = self.count()?;
    self.take(n)
  }
}

#[cfg(test)]
mod tests {
  use super::*;

  fn encoded(payload: &[u8]) -> Vec<u8> {
    let mut out = MAGIC.to_vec();
    out.extend(VERSION.to_le_bytes());
    for n in [0u64, 0, 0] {
      out.extend(n.to_le_bytes());
    }
    let block = Address::hash(b"block");
    out.extend(1u64.to_le_bytes());
    out.extend(block.as_bytes());
    out.extend((payload.len() as u64).to_le_bytes());
    out.extend(payload);
    out.extend(1u64.to_le_bytes());
    out.extend(block.as_bytes());
    out.extend(1u64.to_le_bytes());
    out.extend(Address::hash(b"dep").as_bytes());
    out
  }

  #[test]
  fn decodes_payloads_and_deps() {
    let advice = ModelAdvice::decode(&encoded(b"abc")).expect("decodes");
    let block = Address::hash(b"block");
    assert_eq!(advice.payloads[&block], b"abc");
    assert_eq!(advice.deps[&block], vec![Address::hash(b"dep")]);
  }

  #[test]
  fn rejects_truncated_and_trailing_bytes() {
    let bytes = encoded(b"abc");
    assert!(ModelAdvice::decode(&bytes[..bytes.len() - 1]).is_err());
    let mut long = bytes.clone();
    long.push(0);
    assert!(ModelAdvice::decode(&long).is_err());
  }
}
